func _spawn_player_from_data(data: Variant) -> Node:
	var peer_id: int = int(data)
	var player: Node2D = PLAYER_SCENE.instantiate()
	player.name = "Player_%d" % peer_id
	# Authority is the peer this player represents.
	player.set_multiplayer_authority(peer_id)
	# Pre-position the player if WE are the authority. Setting this
	# before the node enters the tree ensures the synchronizer captures
	# the correct value as its initial state when it enters the tree.
	if player.is_multiplayer_authority():
		player.position = Vector2(float(peer_id), float(peer_id))
	return player
